sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    // The budget application table this rule cares about - must match the Script Include
    var TABLE_NAME = 'x_1962601_budget_t_budget';

    // sys_attachment fires for EVERY deletion in the instance, so exit fast if it is not ours
    if (current.getValue('table_name') !== TABLE_NAME)
        return;

    // Read the file name and lower-case it so extension checking is case-insensitive
    var fileName = ('' + current.getValue('file_name')).toLowerCase();

    // Ignore deletions of non-spreadsheet files - removing a PDF should not change the total
    if (fileName.slice(-5) !== '.xlsx')
        return;

    // Wrap the call so an error never blocks the user's delete action
    try {
        // Recalculate from whatever attachments REMAIN. This row is already gone from the
        // database at "after delete", so the query below will not see the deleted file.
        new BudgetSpreadsheetTotal().recalculate(current.getValue('table_sys_id'));
    } catch (ex) {
        // Record the failure in the system log for an admin to investigate
        gs.error('Budget total recalculation failed after deleting attachment ' +
                 current.getUniqueValue() + ': ' + ex);
    }

})(current, previous);
